def extract_b64_lzma_tar(
    b64_string: str,
    output_dir: str | Path,
    self_path: Optional[str | Path] = None,
    with_deps: bool = False,
) -> None:
    """Decode base64 -> decompress lzma -> extract tar to output_dir, and copy self to dwimsy/meta/unbundle.py."""
    out_path = Path(output_dir).resolve()
    out_path.mkdir(parents=True, exist_ok=True)

    tar_bytes = lzma.decompress(base64.b64decode(b64_string))
    dir_mtimes = {}

    with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:*") as tar:
        members_to_extract = []
        for m in tar.getmembers():
            norm_name = m.name.lstrip("./")
            if not with_deps and (norm_name == "deps" or norm_name.startswith("deps/")):
                continue
            members_to_extract.append(m)
            if m.isdir():
                dir_mtimes[out_path / norm_name] = m.mtime

        try:
            tar.extractall(path=str(out_path), members=members_to_extract, filter="data")
        except TypeError:
            tar.extractall(path=str(out_path), members=members_to_extract)

    # Reconstitute self as dwimsy/meta/unbundle.py in the target tree
    target_unbundle = out_path / "dwimsy" / "meta" / "unbundle.py"
    target_unbundle.parent.mkdir(parents=True, exist_ok=True)

    src_code = None
    if self_path is not None and Path(self_path).is_file():
        try:
            src_code = Path(self_path).read_bytes()
        except OSError:
            pass

    if src_code is None:
        try:
            this_file = Path(__file__).resolve()
            if this_file.is_file():
                src_code = this_file.read_bytes()
        except (NameError, OSError):
            pass

    if src_code is not None:
        target_unbundle.write_bytes(src_code)
        try:
            target_unbundle.chmod(0o755)
        except OSError:
            pass

        # Match unbundle.py mtime to dwimsy/_version.py
        version_file = out_path / "dwimsy" / "_version.py"
        try:
            if version_file.is_file():
                v_mtime = version_file.stat().st_mtime
                os.utime(target_unbundle, (v_mtime, v_mtime))
        except (OSError, PermissionError):
            pass

    # Restore directory mtimes modified during extraction and unbundle.py write
    for dir_path, mtime in dir_mtimes.items():
        try:
            os.utime(dir_path, (mtime, mtime))
        except (OSError, PermissionError):
            pass


def extract_deps(output_dir: str | Path, b64_string: Optional[str] = None) -> List[str]:
    """Extract frozen third-party reference dependencies into output_dir/deps."""
    out_path = Path(output_dir).resolve()
    deps_dir = out_path / "deps"
    deps_dir.mkdir(parents=True, exist_ok=True)

    extracted_names: List[str] = []
    dir_mtimes = {}

    with _open_bundle_tar(b64_string) as tar:
        dep_members = []
        for m in tar.getmembers():
            norm_name = m.name.lstrip("./")
            if norm_name == "deps" or norm_name.startswith("deps/"):
                dep_members.append(m)
                if m.isdir():
                    dir_mtimes[out_path / norm_name] = m.mtime
                elif m.isfile():
                    extracted_names.append(norm_name)

        try:
            tar.extractall(path=str(out_path), members=dep_members, filter="data")
        except TypeError:
            tar.extractall(path=str(out_path), members=dep_members)

    # Restore directory mtimes
    for dir_path, mtime in dir_mtimes.items():
        try:
            os.utime(dir_path, (mtime, mtime))
        except (OSError, PermissionError):
            pass

    return extracted_names


def _open_bundle_tar(b64_string: Optional[str] = None) -> tarfile.TarFile:
    payload = b64_string if b64_string is not None else blztar
    tar_bytes = lzma.decompress(base64.b64decode(payload))
    return tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:*")


def list_assets(b64_string: Optional[str] = None) -> List[str]:
    """List all file paths present in the bundle archive."""
    with _open_bundle_tar(b64_string) as tar:
        names = []
        for m in tar.getmembers():
            if m.isfile():
                name = m.name.lstrip("./")
                names.append(name)
        return names


def get_asset(filename: str, b64_string: Optional[str] = None) -> bytes:
    """Extract a single file from the in-memory bundle payload as raw bytes."""
    norm_target = Path(filename).as_posix().lstrip("./")
    with _open_bundle_tar(b64_string) as tar:
        for m in tar.getmembers():
            if m.isfile() and m.name.lstrip("./") == norm_target:
                f = tar.extractfile(m)
                if f is not None:
                    return f.read()
    raise FileNotFoundError(f"Asset '{filename}' not found in bundle payload")


def get_asset_text(
    filename: str,
    b64_string: Optional[str] = None,
    encoding: str = "utf-8",
) -> str:
    """Extract a single file from the in-memory bundle payload as decoded text."""
    return get_asset(filename, b64_string=b64_string).decode(encoding)


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Extract dwimsy standalone bundle")
    parser.add_argument("target_directory", help="Target directory for extraction")
    parser.add_argument("--deps", "-d", action="store_true", help="Also extract frozen third-party reference dependencies into deps/")
    args = parser.parse_args()
    self_script = sys.argv[0]
    extract_b64_lzma_tar(blztar, args.target_directory, self_path=self_script, with_deps=args.deps)
    print(f"Successfully extracted to {args.target_directory}")

